import React, { useState, useEffect, useContext } from 'react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { useLocation } from 'react-router-dom';
import { submitAntibioticForm } from './api/nurseFormApi';
import { AuthContext } from './App';

const AntibioticForm = () => {
  const { role } = useContext(AuthContext); // Get role from AuthContext
  const location = useLocation();
  const { patientId } = location.state || {};

  const [formData, setFormData] = useState({
    time_induction: '',
    time_incision: '',
    end_time_surgery: '',
  });

  // Patient-specific dummy data
  const patientDummyData = {
    P_7BA294F979676240: {
      time_induction: '08:00',
      time_incision: '08:30',
      end_time_surgery: '10:30',
    },
    P_A1C3F2D49B8E213F: {
      time_induction: '14:00',
      time_incision: '14:15',
      end_time_surgery: '15:45',
    },
    P_8E4D9B76A3C52108: {
      time_induction: '09:00',
      time_incision: '09:30',
      end_time_surgery: '12:30',
    },
  };

  // Pre-fill dummy data for junior_doctor and senior_doctor
  useEffect(() => {
    if ((role === 'junior_doctor' || role === 'senior_doctor') && patientId && patientDummyData[patientId]) {
      setFormData(patientDummyData[patientId]);
    }
  }, [role, patientId]);

  const handleTimeChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Client-side validation
    if (!formData.time_induction) {
      alert('Please fill in Time of Induction');
      return;
    }
    if (!formData.time_incision) {
      alert('Please fill in Time of Incision');
      return;
    }
    if (!formData.end_time_surgery) {
      alert('Please fill in End Time of Surgery');
      return;
    }

    // Prepare payload
    const payload = {
      patient_id: patientId || null, // Include patient_id for backend
      time_induction: formData.time_induction,
      time_incision: formData.time_incision,
      end_time_surgery: formData.end_time_surgery,
    };

    console.log('Sending payload:', payload);

    try {
      const result = await submitAntibioticForm(payload);
      if (result.status === 'SUCCESS') {
        alert('Surgical Timing Form submitted successfully!');
      } else {
        const errorMsg = typeof result.msg === 'object' ? JSON.stringify(result.msg) : result.msg;
        alert(`Server error: ${errorMsg}`);
      }
    } catch (error) {
      console.error('Error:', error.response?.data, error.response?.status);
      const errorMsg = error.response?.data?.msg || error.message;
      alert(`Submission failed: ${typeof errorMsg === 'object' ? JSON.stringify(errorMsg) : errorMsg}`);
    }
  };

  const generatePDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Surgical Timing Form', 20, 20);

    // Time fields
    const timeData = [
      ['Time of Induction', formData.time_induction || 'N/A'],
      ['Time of Incision', formData.time_incision || 'N/A'],
      ['End Time of Surgery', formData.end_time_surgery || 'N/A'],
    ];

    doc.autoTable({
      head: [['Field', 'Value']],
      body: timeData,
      startY: 40,
    });

    doc.save('SurgicalTimingForm.pdf');
  };

  const handleDownloadExcel = () => {
    alert('Downloaded as Excel.');
  };

  return (
    <div style={{ maxWidth: '900px', margin: '0 auto', padding: '20px', border: '1px solid #ccc', borderRadius: '10px', backgroundColor: '#f9f9f9' }}>
      <h2 style={{ textAlign: 'center', marginBottom: '20px' }}>Surgical Timing Form </h2>
      <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
        <label style={{ gridColumn: 'span 1' }}>Time of Induction:</label>
        <input
          type="time"
          name="time_induction"
          value={formData.time_induction}
          onChange={handleTimeChange}
          required
          style={{ gridColumn: 'span 1' }}
        />

        <label style={{ gridColumn: 'span 1' }}>Time of Incision:</label>
        <input
          type="time"
          name="time_incision"
          value={formData.time_incision}
          onChange={handleTimeChange}
          required
          style={{ gridColumn: 'span 1' }}
        />

        <label style={{ gridColumn: 'span 1' }}>End Time of Surgery:</label>
        <input
          type="time"
          name="end_time_surgery"
          value={formData.end_time_surgery}
          onChange={handleTimeChange}
          required
          style={{ gridColumn: 'span 1' }}
        />

        <div style={{ gridColumn: 'span 2', textAlign: 'center' }}>
          <button
            type="submit"
            style={{ marginTop: '20px', padding: '10px 15px', backgroundColor: 'blue', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
          >
            Submit
          </button>
          <button
            type="button"
            onClick={generatePDF}
            style={{
              padding: '10px 20px',
              backgroundColor: 'red',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              marginTop: '20px',
              marginLeft: '10px',
            }}
          >
            Download as PDF
          </button>
          <button
            type="button"
            onClick={handleDownloadExcel}
            style={{
              padding: '10px 20px',
              backgroundColor: '#28a745',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              marginTop: '20px',
              marginLeft: '10px',
            }}
          >
            Download as Excel
          </button>
        </div>
      </form>
    </div>
  );
};

export default AntibioticForm;