import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from './App';
import './SeniorDoctorPage.css';
import logo from './logo.png';

const patients = [
  { id: 'P_7BA294F979676240', name: 'Rachna Singh' },
  { id: 'P_A1C3F2D49B8E213F', name: 'Prabnoor Kaur' },
  { id: 'P_8E4D9B76A3C52108', name: 'Rajeev Kumar' },
];

const SeniorDoctorPage = () => {
  const { role } = useContext(AuthContext);
  const [expandedPatientId, setExpandedPatientId] = useState(null);
  const navigate = useNavigate();

  const togglePatientCard = (patientId) => {
    setExpandedPatientId(expandedPatientId === patientId ? null : patientId);
  };

  const formOptions = [
    { path: '/surveillance-form', label: 'Administration Details' },
    { path: '/surgery-form', label: 'Surgery Details' },
    { path: '/antibiotic-form', label: 'Surgical Timing Details' },
    { path: '/microbiology-form', label: 'Microbiology Details' },
    { path: '/event-details-form', label: 'Event Details' },
    { path: '/ssi-evaluation-form', label: 'SSI Evaluation' },
  ];

  return (
    <div className="senior-doctor-page">
      <div className="taskbar">
        <div className="logo-container">
          <img src={logo} alt="Senior Doctor Portal Logo" className="logo" />
          <h1 className="hospital-name">Senior Doctor Portal </h1>
        </div>
      </div>

      <p className="intro-text">Click on a patient to open their forms:</p>

      <div className="patient-cards-container">
        {patients.map((patient) => (
          <div
            key={patient.id}
            className={`patient-card ${expandedPatientId === patient.id ? 'expanded' : ''}`}
            onClick={() => togglePatientCard(patient.id)}
          >
            <h2>
              <i className="bi bi-person-fill patient-icon"></i>
              {patient.name}
            </h2>
            <p>ID: {patient.id}</p>

            {expandedPatientId === patient.id && (
              <div className="form-buttons">
                {formOptions.map((option) => (
                  <button
                    key={option.path}
                    onClick={(e) => {
                      e.stopPropagation();
                      navigate(option.path, { state: { patientId: patient.id } });
                    }}
                  >
                    {option.label}
                  </button>
                ))}
                <button
                  className="ssi-prediction-button"
                  onClick={(e) => {
                    e.stopPropagation();
                    // Open Streamlit app in a new tab
                    window.open('https://ssi-2nd-app-mta4r2kbubet536dtl8v2f.streamlit.app/', '_blank');
                  }}
                >
                  SSI Prediction
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default SeniorDoctorPage;