import React, { useState, useEffect, useContext } from 'react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { useLocation } from 'react-router-dom';
import { submitMicrobiologyForm } from './api/nurseFormApi';
import { AuthContext } from './App';

const MicrobiologyForm = () => {
  const { role } = useContext(AuthContext);
  const location = useLocation();
  const { patientId } = location.state || {};

  const [formData, setFormData] = useState({
    micro_organism: '',
    secondary_bsi_contribution: '',
    antibiotic_data: [],
  });

  // List of microorganisms
  const micro_organisms = [
    'E COLI',
    'KLEBSIELLA PNEUMONIAE',
    'ENTEROCOCCUS FAECIUM',
    'ENTEROCOCCUS FAECALIS',
    'STAPHYLOCOCCUS HAEMOLYTICUS',
    'SKIN COMMENSAL FLORA',
    'PSEUDOMONAS AERUGINOSA',
    'STAPHYLOCOCCUS AUREUS (MRSA)',
    'STAPHYLOCOCCUS AUREUS (MSSA)',
    'CONS',
    'ACINETOBACTER BAUMANII',
    'CITROBACTER KOSERI',
    'CITROBACTER FREUNDII',
    'ENTEROBACTER CLOACAE',
    'ENTEROBACTER AEROGENES',
    'PROTEUS MIRABILIS',
    'MORGANELLA MORGANII',
    'Others',
  ];

  // List of antibiotics
  const antibiotic_data_list = [
    'Amoxicillin-clavulanic acid',
    'Amikacin',
    'Aztreonam',
    'Cefepime',
    'Ceftazidime',
    'Ceftriaxone',
    'Netilmicin',
    'Meropenem',
    'Imipenem',
    'Levofloxacin',
    'Norfloxacin',
    'Ciprofloxacin',
    'Cefoperazone',
    'Ticarcillin/Clavulanic acid',
    'Piperacillin-tazobactum',
    'Ceftazidime/Avibactam',
    'Penicillin',
    'Oxacillin',
    'Gentamicin',
    'Tetracycline',
    'Clindamycin',
    'Vancomycin E STRIP',
    'Linezolid',
    'Teicoplanin',
    'Nitrofurantoin',
    'Erythromycin',
    'Cefoxitin',
    'Co-trimoxazole',
    'Ertapenem',
    'Chloramphenicol',
    'Fosfomycin',
    'Colistin E STRIP',
    'Cefuroxime',
    'Cefazolin',
    'Vancomycin',
  ];

  // Patient-specific dummy data
  const patientDummyData = {
    P_7BA294F979676240: {
      micro_organism: 'E COLI',
      secondary_bsi_contribution: 'no',
      antibiotic_data: antibiotic_data_list.map((antibiotic) => {
        const defaults = { name: antibiotic, mic: '', interpretation: '' };
        if (antibiotic === 'Ceftriaxone') {
          return { name: antibiotic, mic: '0.5', interpretation: 'Sensitive' };
        }
        if (antibiotic === 'Metronidazole') {
          return { name: antibiotic, mic: '2', interpretation: 'Sensitive' };
        }
        return defaults;
      }),
    },
    P_A1C3F2D49B8E213F: {
      micro_organism: 'STAPHYLOCOCCUS AUREUS (MSSA)',
      secondary_bsi_contribution: 'yes',
      antibiotic_data: antibiotic_data_list.map((antibiotic) => {
        const defaults = { name: antibiotic, mic: '', interpretation: '' };
        if (antibiotic === 'Cefazolin') {
          return { name: antibiotic, mic: '1', interpretation: 'Sensitive' };
        }
        if (antibiotic === 'Vancomycin') {
          return { name: antibiotic, mic: '2', interpretation: 'Sensitive' };
        }
        return defaults;
      }),
    },
    P_8E4D9B76A3C52108: {
      micro_organism: 'STAPHYLOCOCCUS AUREUS (MRSA)',
      secondary_bsi_contribution: 'yes',
      antibiotic_data: antibiotic_data_list.map((antibiotic) => {
        const defaults = { name: antibiotic, mic: '', interpretation: '' };
        if (antibiotic === 'Vancomycin') {
          return { name: antibiotic, mic: '1', interpretation: 'Sensitive' };
        }
        if (antibiotic === 'Linezolid') {
          return { name: antibiotic, mic: '2', interpretation: 'Sensitive' };
        }
        return defaults;
      }),
    },
  };

  // Initialize antibiotic_data and pre-fill dummy data
  useEffect(() => {
    // Initialize antibiotic_data if empty
    if (formData.antibiotic_data.length === 0) {
      const initialAntibioticData = antibiotic_data_list.map((antibiotic) => ({
        name: antibiotic,
        mic: '',
        interpretation: '',
      }));
      setFormData({
        ...formData,
        antibiotic_data: initialAntibioticData,
      });
    }

    // Pre-fill dummy data for junior_doctor and senior_doctor
    if ((role === 'junior_doctor' || role === 'senior_doctor') && patientId && patientDummyData[patientId]) {
      setFormData(patientDummyData[patientId]);
    }
  }, [role, patientId]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleAntibioticChange = (index, field, value) => {
    const updatedAntibioticData = [...formData.antibiotic_data];
    updatedAntibioticData[index] = {
      ...updatedAntibioticData[index],
      [field]: value,
    };
    setFormData({
      ...formData,
      antibiotic_data: updatedAntibioticData,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Client-side validation
    if (!formData.micro_organism) {
      alert('Please select a Micro-organism');
      return;
    }
    if (!formData.secondary_bsi_contribution) {
      alert('Please select Secondary BSI Contribution');
      return;
    }

    // Transform antibiotic_data into flattened structure for backend
    const payload = {
      patient_id: patientId || null,
      micro_organism: formData.micro_organism,
      secondary_bsi_contribution: formData.secondary_bsi_contribution,
    };

    formData.antibiotic_data.forEach((antibiotic) => {
      const key = antibiotic.name.toLowerCase().replace(/[\s/]+/g, '_');
      if (antibiotic.mic || antibiotic.interpretation) {
        payload[`${key}_mic`] = antibiotic.mic || '';
        payload[`${key}_interpretation`] = antibiotic.interpretation || '';
      }
    });

    console.log('Sending payload:', payload);

    try {
      const result = await submitMicrobiologyForm(payload);
      if (result.status === 'SUCCESS') {
        alert('Microbiology form submitted successfully!');
      } else {
        const errorMsg = typeof result.msg === 'object' ? JSON.stringify(result.msg) : result.msg;
        alert(`Server error: ${errorMsg}`);
      }
    } catch (error) {
      console.error('Error:', error.response?.data, error.response?.status);
      const errorMsg = error.response?.data?.msg || error.message;
      alert(`Submission failed: ${typeof errorMsg === 'object' ? JSON.stringify(errorMsg) : errorMsg}`);
    }
  };

  const generatePDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Microbiology Form', 20, 20);

    const generalData = [
      ['Micro-organism', formData.micro_organism || 'N/A'],
      ['Secondary BSI Contribution', formData.secondary_bsi_contribution || 'N/A'],
    ];

    doc.autoTable({
      head: [['Field', 'Value']],
      body: generalData,
      startY: 40,
    });

    const antibioticTableData = formData.antibiotic_data
      .filter((antibiotic) => antibiotic.mic || antibiotic.interpretation)
      .map((antibiotic) => [
        antibiotic.name,
        antibiotic.mic || 'N/A',
        antibiotic.interpretation || 'N/A',
      ]);

    if (antibioticTableData.length > 0) {
      doc.autoTable({
        head: [['Antibiotic', 'MIC', 'Interpretation']],
        body: antibioticTableData,
        startY: doc.lastAutoTable.finalY + 10,
      });
    }

    doc.save('MicrobiologyForm.pdf');
  };

  const handleDownloadExcel = () => {
    alert('Downloaded as Excel.');
  };

  const yesNoOptions = [
    { value: 'yes', label: 'Yes' },
    { value: 'no', label: 'No' },
  ];

  const interpretationOptions = [
    { value: '', label: 'Select Interpretation' },
    { value: 'Resistant', label: 'Resistant' },
    { value: 'Sensitive', label: 'Sensitive' },
    { value: 'Intermediate', label: 'Intermediate' },
    { value: 'Susceptibility_Dose_Dependent', label: 'Susceptibility Dose Dependent' },
  ];

  return (
    <div style={{ maxWidth: '900px', margin: '0 auto', padding: '20px', border: '1px solid #ccc', borderRadius: '10px', backgroundColor: '#f9f9f9' }}>
      <h2 style={{ textAlign: 'center', marginBottom: '20px' }}>Microbiology Form </h2>
      <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
        <label style={{ gridColumn: 'span 1' }}>Micro-organism implicated for SSI event:</label>
        <select
          name="micro_organism"
          value={formData.micro_organism}
          onChange={handleInputChange}
          required
          style={{ gridColumn: 'span 1' }}
        >
          <option value="">Select Micro-organism</option>
          {micro_organisms.map((organism, index) => (
            <option key={index} value={organism}>{organism}</option>
          ))}
        </select>

        <label style={{ gridColumn: 'span 1' }}>Secondary BSI Contribution:</label>
        <div style={{ gridColumn: 'span 1' }}>
          {yesNoOptions.map((opt) => (
            <label key={opt.value}>
              <input
                type="radio"
                name="secondary_bsi_contribution"
                value={opt.value}
                checked={formData.secondary_bsi_contribution === opt.value}
                onChange={handleInputChange}
                required
              /> {opt.label}
            </label>
          ))}
        </div>

        <div style={{ gridColumn: 'span 2', marginTop: '20px' }}>
          <h3 style={{ textAlign: 'center' }}>Antibiotic Susceptibility Data</h3>
          <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
            <thead>
              <tr>
                <th style={{ border: '1px solid #000', padding: '10px', textAlign: 'center' }}>Antibiotic</th>
                <th style={{ border: '1px solid #000', padding: '10px', textAlign: 'center' }}>MIC</th>
                <th style={{ border: '1px solid #000', padding: '10px', textAlign: 'center' }}>Interpretation</th>
              </tr>
            </thead>
            <tbody>
              {formData.antibiotic_data.map((antibiotic, index) => (
                <tr key={index}>
                  <td style={{ border: '1px solid #000', padding: '10px', textAlign: 'center' }}>{antibiotic.name}</td>
                  <td style={{ border: '1px solid #000', padding: '10px', textAlign: 'center' }}>
                    <input
                      type="text"
                      value={antibiotic.mic}
                      onChange={(e) => handleAntibioticChange(index, 'mic', e.target.value)}
                      style={{ width: '80px', padding: '5px' }}
                    />
                  </td>
                  <td style={{ border: '1px solid #000', padding: '10px', textAlign: 'center' }}>
                    <select
                      value={antibiotic.interpretation}
                      onChange={(e) => handleAntibioticChange(index, 'interpretation', e.target.value)}
                      style={{ width: '150px', padding: '5px' }}
                    >
                      {interpretationOptions.map((opt) => (
                        <option key={opt.value} value={opt.value}>
                          {opt.label}
                        </option>
                      ))}
                    </select>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div style={{ gridColumn: 'span 2', textAlign: 'center' }}>
          <button
            type="submit"
            style={{ marginTop: '20px', padding: '10px 15px', backgroundColor: 'blue', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
          >
            Submit
          </button>
          <button
            type="button"
            onClick={generatePDF}
            style={{
              padding: '10px 20px',
              backgroundColor: 'red',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              marginTop: '20px',
              marginLeft: '10px',
            }}
          >
            Download as PDF
          </button>
          <button
            type="button"
            onClick={handleDownloadExcel}
            style={{
              padding: '10px 20px',
              backgroundColor: '#28a745',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              marginTop: '20px',
              marginLeft: '10px',
            }}
          >
            Download as Excel
          </button>
        </div>
      </form>
    </div>
  );
};

export default MicrobiologyForm;