import React, { useState, useEffect, useContext } from 'react';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { useLocation } from 'react-router-dom';
import { AuthContext } from './App';
import { submitSurgeryForm } from './api/nurseFormApi';

const SurgeryForm = () => {
  const { role } = useContext(AuthContext);
  const location = useLocation();
  const { patientId } = location.state || {};

  const [data, setData] = useState({
    date_procedure: '',
    name_procedure: '',
    postOpDay: '',
    day1: '', day2: '', day3: '', day4: '', day5: '', day6: '', day7: '', day8: '', day9: '',
    day10: '', day11: '', day12: '', day13: '', day14: '', day15: '', day16_30: '', day31_60: '', day60_90: '',
    purulent_discharge: '',
    localized_pain: '',
    localized_swelling: '',
    fever: '',
    incision_deliberately_opened: '',
    spontaneous_dehiscence: '',
    abscess: '',
    microorganisms_seen: '',
    imaging_evidence: '',
    positive_culture: '',
    blood_culture_sent: '',
    physician_diagnosis: '',
    any_other: '',
  });

  // Patient-specific dummy data (flattened to match original state)
  const patientDummyData = {
    P_7BA294F979676240: {
      date_procedure: '2025-05-03',
      name_procedure: 'Gallbladder surgery',
      postOpDay: '',
      day1: '', day2: '', day3: '', day4: '', day5: '', day6: '', day7: '', day8: '', day9: '',
      day10: '', day11: '', day12: '', day13: '', day14: '', day15: '', day16_30: '', day31_60: '', day60_90: '',
      purulent_discharge: 'Yes',
      localized_pain: 'Moderate',
      localized_swelling: 'Yes',
      fever: '38.5°C',
      incision_deliberately_opened: '',
      spontaneous_dehiscence: '',
      abscess: 'Yes',
      microorganisms_seen: 'Gram-negative',
      imaging_evidence: 'Ultrasound: Abscess',
      positive_culture: 'E. coli',
      blood_culture_sent: 'No',
      physician_diagnosis: 'Organ/Space SSI',
      any_other: '',
    },
    P_A1C3F2D49B8E213F: {
      date_procedure: '2025-05-02',
      name_procedure: 'Cesarean section',
      postOpDay: '',
      day1: '', day2: '', day3: '', day4: '', day5: '', day6: '', day7: '', day8: '', day9: '',
      day10: '', day11: '', day12: '', day13: '', day14: '', day15: '', day16_30: '', day31_60: '', day60_90: '',
      purulent_discharge: 'Yes',
      localized_pain: 'Mild',
      localized_swelling: 'Yes',
      fever: '37.8°C',
      incision_deliberately_opened: 'Yes',
      spontaneous_dehiscence: '',
      abscess: '',
      microorganisms_seen: 'Gram-positive',
      imaging_evidence: '',
      positive_culture: 'MSSA',
      blood_culture_sent: 'Yes',
      physician_diagnosis: 'SIP SSI',
      any_other: '',
    },
    P_8E4D9B76A3C52108: {
      date_procedure: '2025-05-02',
      name_procedure: 'Hip prosthesis',
      postOpDay: '',
      day1: '', day2: '', day3: '', day4: '', day5: '', day6: '', day7: '', day8: '', day9: '',
      day10: '', day11: '', day12: '', day13: '', day14: '', day15: '', day16_30: '', day31_60: '', day60_90: '',
      purulent_discharge: '',
      localized_pain: 'Severe',
      localized_swelling: 'Yes',
      fever: '39.0°C',
      incision_deliberately_opened: '',
      spontaneous_dehiscence: 'Yes',
      abscess: '',
      microorganisms_seen: 'Gram-positive',
      imaging_evidence: 'MRI: Deep infection',
      positive_culture: 'MRSA',
      blood_culture_sent: 'Yes',
      physician_diagnosis: 'DIP SSI',
      any_other: '',
    },
  };

  // Pre-fill for doctors
  useEffect(() => {
    if ((role === 'junior_doctor' || role === 'senior_doctor') && patientId && patientDummyData[patientId]) {
      setData(patientDummyData[patientId]);
    }
  }, [role, patientId]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await submitSurgeryForm(data);
      console.log('Form submitted:', response);
      alert('Form submitted successfully!');
    } catch (error) {
      console.error('Submission error:', error);
      alert('Failed to submit form.');
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setData({ ...data, [name]: value });
  };

  const handleDownloadPDF = () => {
    const doc = new jsPDF();
    doc.text('Surgery Procedure Report', 10, 10);

    // Add Patient/Procedure Details
    doc.text(`Date of Procedure: ${data.date_procedure || 'N/A'}`, 10, 20);
    doc.text(`Name of Procedure: ${data.name_procedure || 'N/A'}`, 10, 30);

    // Create Table for Events
    const columns = ['Event', 'Value'];
    const rows = [
      ['Purulent Discharge from incision/wound', data.purulent_discharge || ''],
      ['Localized Pain and tenderness', data.localized_pain || ''],
      ['Localized Swelling', data.localized_swelling || ''],
      ['Fever', data.fever || ''],
      ['Incision deliberately opened / drained', data.incision_deliberately_opened || ''],
      ['Spontaneous dehiscence of wound', data.spontaneous_dehiscence || ''],
      ['Abscess', data.abscess || ''],
      ['Micro-organisms seen in Gram\'s staining', data.microorganisms_seen || ''],
      ['Imaging evidence of infection/abscess', data.imaging_evidence || ''],
      ['Positive culture from discharge material', data.positive_culture || ''],
      ['Blood culture sent', data.blood_culture_sent || ''],
      ['Physician Institutes a Diagnosis of SSI', data.physician_diagnosis || ''],
      ['Any Other', data.any_other || ''],
    ];

    doc.autoTable({
      head: [columns],
      body: rows,
      startY: 40,
      theme: 'grid',
      styles: { fontSize: 8, cellPadding: 2 },
      columnStyles: { 0: { cellWidth: 60 } },
    });

    doc.save('Surgery_Procedure_Report.pdf');
  };

  const handleDownloadExcel = () => {
    alert('Downloaded as Excel.');
  };

  return (
    <div style={{ width: '100%', margin: '0 auto', backgroundColor: '#f4f4f4', padding: '20px', borderRadius: '8px' }}>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column' }}>
        <h2>Surgery Procedure Form</h2>

        <div style={{ marginBottom: '20px' }}>
          <label>
            Date of Procedure:
            <input
              type="date"
              name="date_procedure"
              value={data.date_procedure}
              onChange={handleChange}
              style={inputStyle}
            />
          </label>
        </div>
        <div style={{ marginBottom: '20px' }}>
          <label>
            Name of Procedure:
            <input
              type="text"
              name="name_procedure"
              value={data.name_procedure}
              onChange={handleChange}
              style={inputStyle}
            />
          </label>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center' }}>
          <thead>
            <tr>
              <th style={tableHeaderStyle}>Event</th>
              <th style={tableHeaderStyle}>Value</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td style={tableCellStyle}>Purulent Discharge from incision/wound</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="purulent_discharge"
                  value={data.purulent_discharge}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Localized Pain and tenderness</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="localized_pain"
                  value={data.localized_pain}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Localized Swelling</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="localized_swelling"
                  value={data.localized_swelling}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Fever</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="fever"
                  value={data.fever}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Incision deliberately opened / drained</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="incision_deliberately_opened"
                  value={data.incision_deliberately_opened}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Spontaneous dehiscence of wound</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="spontaneous_dehiscence"
                  value={data.spontaneous_dehiscence}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Abscess</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="abscess"
                  value={data.abscess}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Micro-organisms seen in Gram's staining</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="microorganisms_seen"
                  value={data.microorganisms_seen}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Imaging evidence of infection/abscess</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="imaging_evidence"
                  value={data.imaging_evidence}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Positive culture from discharge material</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="positive_culture"
                  value={data.positive_culture}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Blood culture sent</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="blood_culture_sent"
                  value={data.blood_culture_sent}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Physician Institutes a Diagnosis of SSI</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="physician_diagnosis"
                  value={data.physician_diagnosis}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
            <tr>
              <td style={tableCellStyle}>Any Other</td>
              <td style={tableCellStyle}>
                <input
                  type="text"
                  name="any_other"
                  value={data.any_other}
                  onChange={handleChange}
                  style={inputStyle}
                />
              </td>
            </tr>
          </tbody>
        </table>

        <button
          type="submit"
          style={{
            marginTop: '20px',
            padding: '10px 15px',
            backgroundColor: 'blue',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
          }}
        >
          Submit
        </button>
        <button
          type="button"
          onClick={handleDownloadPDF}
          style={{
            marginTop: '20px',
            padding: '10px 15px',
            backgroundColor: 'red',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            marginLeft: '10px',
          }}
        >
          Download as PDF
        </button>
        <button
          type="button"
          onClick={handleDownloadExcel}
          style={{
            padding: '10px 20px',
            backgroundColor: '#28a745',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            marginTop: '20px',
            marginLeft: '10px',
          }}
        >
          Download as Excel
        </button>
      </form>
    </div>
  );
};

// Inline styles for table elements
const tableHeaderStyle = {
  backgroundColor: '#ddd',
  padding: '10px',
  border: '1px solid #ccc',
  textAlign: 'center',
};

const tableCellStyle = {
  padding: '10px',
  border: '1px solid #ccc',
};

const inputStyle = {
  width: '100%',
  padding: '8px',
  border: '1px solid #ccc',
  borderRadius: '4px',
};

export default SurgeryForm;